INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65823984', 65823984, 'analyze_legacy', 'Kementerian Hukum', 'central', 'DIREKTORAT JENDERAL PERATURAN PERUNDANG UNDANGAN', 'Pengadaan Tiket Pesawat PP Bisnis, Bali Kegiatan Konsultasi Publik Penyusunan Naskah Akademik RUU Pada Direktorat Perencanaan Peraturan Perundang-Undangan Direktorat Jenderal Peraturan Perundang-Undangan Tahun Anggaran 2026', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 3448000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 1, OK, @ 3448000 )', '1. Tiket Pesawat PP Bisnis, Bali ( 1, OK, @ 3448000 );', '1. Tiket Pesawat PP Bisnis, Bali ( 1, OK, @ 3448000 );', 3448000, 'high', 'Pengadaan tiket pesawat pulang-pergi kelas bisnis untuk perjalanan domestik menunjukkan standar fasilitas yang berlebihan untuk penggunaan dana publik. Dari judul dan spesifikasi, kebutuhan perjalanan tidak dijustifikasi sebagai kondisi khusus yang menuntut kelas bisnis, sehingga seluruh nilai item layak dicermati sebagai potensi pemborosan.', NULL, NULL, 3, 1, 1, 1, 1, 2350795);
