INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65828001', 65828001, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'SEKRETARIAT DIREKTORAT JENDERAL FARMASI DAN ALAT KESEHATAN', 'Penyediaan Reagen Pemeriksa Spesimen Campak-Rubella/CRS Tahun 2026', 'Barang', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 2484500000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 0, 0, '1 PT', 'Belanja Barang Bantuan Lainnya Untuk Diserahkan Kepada Masyarakat/Pemda dengan Menyediakan Logistik Pemeriksa Spesimen Campak-Rubella/CRS Tahun 2026 berupa IgM Campak, IgM Rubella dan IgG Rubella', 'Spesifikasi Logistik Pemeriksa Spesimen Campak-Rubella/CRS sebagai berikut : 1. Reagensia IgM Campak : Kegunaan : Kit uji ELISA menyediakan uji semikuantitatif in vitro untuk antibodi manusia dari kelas lgM terhadap nukleoprotein virus campak (virus campak NP) dalam serum atau plasma; Ringkasan dan Penjelasan : Pengujian speslfik lgM Campak yang digunakan untuk mendiagnosis penyakit akibat paparan virus Campak; Prinsip Metode : Kit uji berisi strip mikrotiter, masing-masing strip dengan 8 sumur/lubang yang dilapisi dengan rekombinan nukleoprotein virus campak. Pada langkah reaksi pertama, sampel pasien yang diencerkan diinkubasi di dalam sumur. Dalam kasus sampel positif, antibodi lgM spesifik juga lgA dan lgG) akan berikatan dengan antigen. Untuk mendeteksi antibodi yang terikat, inkubasi kedua dilakukan menggunakan anti-manusia IgM berlabel enzim (enzim konjugat). Kompleks ikatan yang terbentuk akan mengkatalisasi reaksi warna pada substrat; Metode analisis : Kolorimetrik immunoassay; Jenis Sampel : serum dan plasma; Kemasan : 1 kit untuk 96 test; Reagen (lsi kemasan kit) : - Mikrotiter yang dilapisi rekombinan nukleoprotein virus campak, - Calibrator, - Kontrol Positif, - Kontrol Negatif, - Enzym Conjugate (peroxidase-labelled anti-human IgM), - Sampel Diluent (berisi lgG/RF-Absorbent (Anti-human lgG antibody preparation obtained from goat)), - Buffer Pencuci (konsentrasi 10x), - Larutan Chromogen/substrat (TMB dalam H2O2), - Larutan Penyetop (Stop Solution), - Insert kit,- Sertifikat Quality Control; Penyimpanan dan Stabilitas : Semua kit reagen yang belum dibuka dapat digunakan sampai tanggal kadaluarsa yang tertera pada label. Penyimpanan pada suhu 2 - 8°C (Suhu Refrigerator); Sensitifitas dan Spesifitas : Lebih dari 95%. Tanggal kadaluarsa : Minimal 6 bulan setelah diterima laboratorium; 2. Reagensia IgM Rubella : Kegunaan : Kit uji ELISA menyediakan uji semikuantitatif in vitro untuk antibodi IgM manusia terhadap virus Rubella dalam serum atau plasma. Ringkasan dan Penjelasan : Pengujian spesifik lgM Rubella yang digunakan untuk mendiagnosis penyakit akibat paparan virus Rubella. Prinsip Metode : Kit tes berisi strip mikrotiter, masing-masing strip berisi 8 sumur/ lubang yang dilapisi dengan antigen virus Rubella. Pada langkah reaksi pertama, sampel pasien yang diencerkan diinkubasi di dalam sumur/lubang. Dalam kasus sampel positif, antibodi IgM spesifik akan berikatan dengan antigen. Untuk mendeteksi antibodi yang terikat, inkubasi kedua dilakukan menggunakan IgM antimanusia berlabel enzim (konjugat enzim) yang mengkatalisis reaksi warna. Metode analisis : Kolorimetrik immunoassay. Jenis Sampel : serum dan plasma. Kemasan : 1 kit untuk 96 test. Reagen (lsi kemasan kit) : - Mikrotiter yang dilapisi antigen virus Rubella - Calibrator - Kontrol Positif - Kontrol Negatif - Enzym Conjugate (peroxidase-labelled anti-human lgM) - Sampel Buffer (berisi lgG/RF-Absorbent (Anti-human lgG antibody preparation obtained from goat)) - Buffer Pencuci (konsentrasi 10x) - Larutan Chromogen/substrat (TMB dalam H2O2) - Larutan Penyetop (Stop Solution) - Insert kit - Sertifikat Quality Control Penyimpanan dan Stabilitas : Semua kit reagen yang belum dibuka dapat digunakan sampai tanggal kadaluarsa yang tertera pada label. Penyimpanan pada suhu 2 - 8°C (Suhu Refrigerator). Sensitifitas dan Spesifitas : Lebih dari 95%. Tanggal kadaluarsa : Minimal 6 bulan setelah diterima laboratorium; 3. Reagensia IgG Rubella : Kegunaan : Kit uji ELISA menyediakan uji semikuantitatif in vitro untuk antibody IgG manusia terhadap virus Rubella dalam serum atau plasma. Ringkasan dan Penjelasan : Pengujian spesifik IgG rubella yang digunakan untuk mendiagnosis penyakit akibat paparan virus Rubella. Prinsip Metode : Kit tes berisi strip rnikrotiter, rnasing-masing dengan 8 sumur reagen yang dilapisi dengan antigen virus Rubella. Pada langkah reaksi pertama, sampel pasien yang diencerkan diinkubasi di dalam sumur. Dalam kasus sampel positif, antibody IgG spesifikasi akan berikatan dengan antigen. Untuk mendeteksi antibodi yang terikat, inkubasi kedua dilakukan menggunakan IgG antimanusia berlabel enzim (konjugat enzim) yang mengkatalisis reaksi warna. Metode analisis : Kolorimetrik immunoassay. Jenis Sampel : serum dan plasma. Kemasan : 1 kit untuk 96 test. Reagen (lsi kemasan kit) : - Mikrotiter yang dilapisi antigen virus Rubella - Calibrator - Kontrol Positif - Kontrol Negatif - Enzym Conjugate (peroxidase-labelled anti-human IgG) - Sampel Buffer - Buffer Pencuci (konsentrasi 10x) - Larutan Chromogen/substrat (TMB dalam H2O2) - Larutan Penyetop (Stop Solution) - Insert kit - Sertifikat Quality Control. Penyimpanan dan Stabilitas : Semua kit reagen yang belum di buka dapat digunakan sampai tanggal kadaluarsa yang tertera pada label. Penyimpanan pada suhu 2 - 80C (Suhu Refrigerator). Sensitifitas dan Spesifitas : Lebih dari 95%. Tanggal kadaluarsa : Minimal 6 bulan setelah diterima laboratorium.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2357130);
