INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65830142', 65830142, 'analyze_legacy', 'Pusat Pelaporan Dan Analisis Transaksi Keuangan', 'central', 'Pendidikan dan Pelatihan Anti Pencucian Uang PPATK', 'Pemeliharaan Genset', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Barat, Depok (Kota)', 80330000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '3 Unit', 'a. 2 (dua) unit Genset 500 kVA di Pusdiklat APUPPT dan 1 (satu) unit Genset 250kVA di Gedung Arsip Ciloto berada dalam kondisi siap operasi dan mampu berfungsi normal sebagai sumber listrik cadangan. b. Genset mampu menyala dan beroperasi stabil saat dilakukan pengujian maupun simulasi beban. c. Seluruh sistem utama genset, meliputi mesin, sistem bahan bakar, sistem pelumasan, sistem pendingin, dan sistem kelistrikan, berfungsi dengan baik. d. Tidak terdapat kebocoran oli, bahan bakar, atau coolant setelah pekerjaan pemeliharaan. e. Parameter operasional genset (tegangan, frekuensi, suhu, dan tekanan oli) berada dalam batas normal. f. Hasil pemeliharaan didukung dengan laporan pekerjaan dan dilengkapi garansi layanan sesuai ketentuan.', 'Gedung Pusdiklat APUPPT 1. Pemeliharaan Genset 500kVA (2 Unit 2 Kegiatan): a. Unit Clean Up b. Check Diesel Fuel c. Check Oil Engine d. Check Fanbelt Alternator e. Check Fanbelt As Engine f. Check Radiator Water g. Check Genset Temperature h. Check Genset Oil Pressure i. Check Simulation System j. Cleaning Genset k. Radiator Cleaning 2. Penggantian Parts Genset 500kVA (termasuk jasa penggantian) a. Oli Mediteran SX SAE 40 : 140 Lt b. Filter Oli Perkins CH10929 : 2 Pcs c. Filter Fuel Primary Perkins CH10930 : 2 Pcs d. Filter Fuel Secondary Perkins CH10931 : 2 Ltr e. Water Coolant Megacools Green : 120 Ltr f. Filter Water Separator Parker 2020 PM : 2 Pcs g. Air Cleaner Genuine Perkins CH11038 : 2 Unit h. Battery GS Astra N120 : 4 Unit Gedung Arsip Ciloto 1. Pemeliharaan Genset 250kVA (1 Unit 2 Kegiatan) a. Unit Clean Up b. Check Diesel Fuel c. Check Oil Engine d. Check Fanbelt Alternator e. Check Fanbelt As Engine f. Check Radiator Water g. Check Genset Temperature h. Check Genset Oil Pressure i. Check Simulation System j. Cleaning Genset k. Radiator Cleaning 2. Penggantian Parts Genset 250kVA (termasuk jasa penggantian): a. Oli Mediteran SX SAE 40 : 60 Ltr b. Filter Oli Genuine Cummins LF3000 : 1 Unit c. Filter Fuel Primary Cummins FS1280 : 1 Unit d. Filter Fuel Secondary Cummins FF5052 : 1 Unit e. Filter Water Separator Parker 2010 PM : 1 Unit f. Battery GS Astra N120 : 2 Unit g. Water Coolant Megacools Green : 60 Liter Tenaga Teknis : - Minimal 1 (satu) orang, bersertifikat terkait dengan Pemeliharaan Genset, dengan pengalaman kerja minimal 1 (satu) tahun di Pemeliharaan Genset. Peralatan : 1. Tang Amper 2 Buah 2. Multi Tester 2 Buah 3. Tespen 2 Buah 4. Kunci Pas 2 Buah 5. Tang 2 Buah 6. Kunci Inggris 2 Buah 7. Torque Wrench 2 Buah 8. Termometer Laser 2 Buah 9. Sarung Tangan 3 Set', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2358635);
