INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('65829346', 65829346, 'analyze_legacy', 'Kota Probolinggo', 'kabkota', 'SEKRETARIAT DPRD', 'Belanja Jasa Tenaga Keamanan', 'Jasa Lainnya', 'E-Purchasing', 'Jawa Timur, Probolinggo (Kota)', 275000000, 'December 2025', 'APBD', 1, 1, '1 Paket', 'Dalam rangka mendukung kelancaran pelaksanaan tugas dan fungsi Sekretariat DPRD Kota Probolinggo, diperlukan lingkungan kerja yang aman, tertib, dan kondusif. Aktivitas kedewanan yang meliputi kegiatan rapat, kunjungan kerja, penerimaan aspirasi masyarakat, serta pengelolaan administrasi dan aset negara menuntut adanya sistem pengamanan yang memadai dan berkelanjutan. Seiring meningkatnya intensitas kegiatan serta mobilitas pimpinan dan anggota DPRD, potensi risiko terhadap keamanan personel, dokumen, dan sarana prasarana perlu diantisipasi secara optimal. Pengamanan yang efektif tidak hanya berperan dalam pencegahan gangguan keamanan, tetapi juga sebagai bagian dari upaya menjaga ketertiban, kedisiplinan, serta kenyamanan lingkungan kerja di Sekretariat DPRD Kota Probolinggo. Berdasarkan pertimbangan tersebut, pengadaan tenaga keamanan menjadi kebutuhan strategis guna menjamin terselenggaranya pelayanan administrasi dan fasilitasi kegiatan DPRD secara aman dan profesional. Kehadiran tenaga keamanan diharapkan mampu mendukung terciptanya tata kelola pemerintahan yang baik (good governance), meningkatkan rasa aman bagi seluruh pemangku kepentingan, serta menjaga aset dan fasilitas milik daerah agar tetap terpelihara dengan baik.', '6 Orang Tenaga Keamanan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2359065);
